"""Batch KULIT C (dermatitis & erupsi, 12) + TRAUMA & FORENSIK (4)."""
from lib import C, CX, D, F, PF, T, NT, SY, W, X, REF_PPK

SYS = "Kulit & kelamin"
TR = "Trauma & forensik"
REF_KK = [REF_PPK, "PERDOSKI. Panduan Praktik Klinis bagi Dokter Spesialis Dermatologi dan Venereologi Indonesia (2021)"]
REF_TR = [REF_PPK, "ATLS (American College of Surgeons) — prinsip penanganan luka", "Kemenkes RI. Pedoman Penatalaksanaan Luka Bakar (PNPK 2019)"]
REF_FOR = [REF_PPK, "Budiyanto A, dkk. Ilmu Kedokteran Forensik — Visum et Repertum", "UU No. 23/2004 tentang Penghapusan KDRT"]


def DS(lok, efl, khusus=None, when=None, p=None, diag=True):
    out = [F("status_dermatologis", "lokasi", lok, when=when, p=p), F("status_dermatologis", "efloresensi", efl, when=when, p=p, diag=diag)]
    if khusus:
        out.append(F("status_dermatologis", "tanda_khusus", khusus, when=when, p=p))
    return out


C("dermatitis_kontak_alergi", "Dermatitis kontak alergi", SYS, "rendah", "Reaksi tipe IV terhadap alergen (nikel, karet, pewarna rambut): gatal dominan, vesikel, dapat menyebar di luar area kontak.")
C("eksema_herpetikum", "Eksema herpetikum", SYS, "kritis", "Infeksi HSV luas pada dermatitis atopik: vesikel & erosi punched-out monomorf, demam. Asiklovir & rujuk segera.")
