# 6 ---------------------------------------------------------------------------------- pitiriasis rosea
D(id="pitiriasis_rosea", name="Pitiriasis rosea", aka=["Pityriasis rosea", "Ruam pohon cemara"],
  sys=SYS, prev=0.8,
  summary="Erupsi papuloskuamosa akut swasirna (diduga reaktivasi HHV-6/7) pada remaja & dewasa muda: diawali satu lesi besar oval eritematosa-salmon berskuama koleret (herald patch), 1–2 minggu kemudian diikuti erupsi sekunder lesi oval lebih kecil di badan yang sumbu panjangnya sejajar garis kulit (pola pohon cemara), gatal ringan. Sembuh sendiri 6–8 minggu. Singkirkan sifilis sekunder & tinea.",
  day=(10, 21), ages=[(10, 20, 3), (21, 35, 4), (36, 50, 1)], male=0.45,
  traits=[("prodromal", 0.3)], tl={"prodromal": "Didahului gejala seperti flu."},
  sym=[("ruam_kulit", 1), ("gatal_kulit", 0.5), ("demam", 0.6, T("prodromal")), ("lemas", 0.4, T("prodromal"))],
  cc=["ruam_kulit"], ex=["gatal_kulit"], mis=["kurap", "panu", "alergi"], fears=["penyakit kelamin", "menular"],
  ana={
      "onset": [("Dua minggu lalu muncul satu bercak besar di dada, Dok, seminggu kemudian bercak-bercak kecil menyebar di badan.", "Herald patch diikuti erupsi sekunder")],
      "karakter": [("Bercaknya lonjong, pinggirnya bersisik halus, cuma sedikit gatal, Dok.", "Lesi oval dengan skuama koleret, gatal ringan")],
      "lokasi": [("Di badan dan lengan atas, Dok, telapak tangan dan kaki bersih.", "Badan & proksimal, telapak tidak terkena")],
      "kebiasaan": [("Belum pernah berhubungan seksual berisiko, Dok.", "Tanpa faktor risiko sifilis", W(amin=18)), ("Masih sekolah, Dok.", None, W(amax=17))],
      "riwayat_obat": [("Nggak minum obat baru sebelum ruamnya muncul, Dok.", "Tanpa obat baru (bukan erupsi obat)")],
  },
  f=DS("Badan & ekstremitas proksimal, sumbu panjang sejajar garis kulit (pola pohon cemara)", "Makula-plak oval eritematosa-salmon dengan skuama koleret; satu lesi lebih besar (herald patch) di dada")
    + [F("kerokan_koh", "hasil", "Tidak ditemukan hifa, spora, maupun pseudohifa"), F("tes_sifilis", "rpr", "Non-reaktif"), F("tes_sifilis", "tpha", "Non-reaktif")],
  dd=[
      X("sifilis", "Sifilis sekunder: ruam papuloskuamosa termasuk TELAPAK tangan/kaki, limfadenopati, faktor risiko; serologi reaktif.", ["lokasi", "tes_sifilis"], must=True),
      X("tinea_korporis", "Tinea korporis: tepi aktif dengan central healing, KOH positif.", ["kerokan_koh"]),
      X("erupsi_obat", "Erupsi obat: riwayat obat baru, makulopapular simetris.", ["riwayat_obat"]),
      X("psoriasis", "Psoriasis gutata: papul skuama tebal keperakan setelah infeksi tenggorok.", ["status_dermatologis"]),
  ],
  key=["Herald patch lalu erupsi sekunder lesi oval berskuama koleret", "Pola pohon cemara, telapak tidak terkena", "Swasirna 6–8 minggu"],
  teach=["Pada ruam papuloskuamosa dewasa muda, serologi sifilis sederhana mencegah salah diagnosis yang berbahaya."],
  plan=dict(topics=["onset", "karakter", "lokasi", "kebiasaan", "riwayat_obat", "keluhan_lain"],
            exams=[("status_dermatologis", "kunci", "Herald patch & pola distribusi.")],
            tests=[("kerokan_koh", "pendukung", "Menyingkirkan tinea."), ("tes_sifilis", "pendukung", "Menyingkirkan sifilis sekunder.")]),
  disp=[("rawat_jalan", "Edukasi swasirna, emolien & antihistamin, steroid topikal ringan bila gatal; kontrol bila tidak membaik 8 minggu.")],
  mg=["Edukasi: tidak menular berarti, sembuh sendiri dalam 6–8 minggu, bisa meninggalkan perubahan warna sementara.", "Emolien, antihistamin oral; kortikosteroid topikal ringan bila gatal.",
      "Hindari sabun keras & pakaian ketat."],
  ap=["Kenali herald patch & pola cemara.", "Singkirkan sifilis & tinea."],
  refs=REF_KK)

# 7 ---------------------------------------------------------------------------------- akne vulgaris
D(id="akne_vulgaris", name="Akne vulgaris ringan", aka=["Jerawat", "Acne", "Akne"],
  sys=SYS, prev=1.6,
  summary="Peradangan kronik unit pilosebasea pada remaja-dewasa muda: komedo terbuka (blackhead) & tertutup (whitehead), papul, pustul di wajah, dada, punggung. Ringan: dominan komedo atau papulopustul sedikit tanpa nodul/kista. Pencetus: hormon (menjelang haid), kosmetik komedogenik, memencet, stres. Terapi topikal: retinoid ± benzoil peroksida ± antibiotik topikal (kombinasi), 8–12 minggu.",
  day=(30, 365), ages=[(12, 18, 5), (19, 30, 3)], male=0.5,
  occ=[("pelajar", 4), ("mahasiswa", 3)], bias=0.5,
  traits=[("kosmetik", 0.35, W(sex="female")), ("memencet", 0.6), ("pencetus_haid", 0.5, W(sex="female"))],
  tl={"kosmetik": "Kosmetik/krim tebal komedogenik.", "memencet": "Kebiasaan memencet jerawat.", "pencetus_haid": "Kambuh menjelang haid."},
  sym=[("jerawat", 1)],
  cc=["jerawat"], mis=["kotor", "makanan berminyak", "masa puber biasa"], fears=["bekas jerawat permanen", "minder"],
  ana={
      "onset": [("Sejak SMP, Dok, jerawatan di muka, kambuh-kambuhan.", "Onset remaja, kronik")],
      "pola": [("Makin banyak menjelang haid, Dok.", "Kambuh menjelang haid", T("pencetus_haid")), ("Kalau stres ujian makin banyak, Dok.", "Memberat saat stres", NT("pencetus_haid"))],
      "kebiasaan": [("Pakai krim pemutih dan foundation tebal tiap hari, Dok.", "Kosmetik komedogenik", T("kosmetik")),
                    ("Sering saya pencet-pencet, Dok.", "Memencet jerawat", T("memencet")), ("Cuci muka pakai sabun biasa, Dok.", None, W(nt=["kosmetik", "memencet"]))],
      "riwayat_penyakit": [("Haid saya teratur, Dok, nggak ada bulu berlebih.", "Tanpa tanda hiperandrogenisme", W(sex="female")),
                           ("Nggak pernah minum obat steroid atau suplemen otot, Dok.", "Tanpa pencetus obat", W(sex="male"))],
      "keparahan": [("Nggak ada benjolan besar yang sakit, Dok, cuma bintik-bintik dan komedo.", "Tanpa nodul/kista (ringan)")],
  },
  f=DS("Wajah (dahi, pipi, dagu)", "Komedo terbuka & tertutup multipel, papul eritematosa < 10, beberapa pustul; tanpa nodul/kista",
       "Hiperpigmentasi pascainflamasi bekas memencet")
    + [F("status_dermatologis", "rambut_kuku", "Tidak ada hirsutisme")],
  dd=[
      X("sindrom_ovarium_polikistik", "PCOS: akne membandel dengan haid tidak teratur, hirsutisme, obesitas — evaluasi lanjut.", ["riwayat_penyakit", "status_dermatologis"], must=True),
      X("dermatitis_perioral", "Dermatitis perioral: papul-pustul sekitar mulut tanpa komedo, riwayat steroid topikal.", ["status_dermatologis"]),
      X("folikulitis", "Folikulitis: pustul folikular monomorf tanpa komedo.", ["status_dermatologis"]),
      X("rosasea", "Rosasea: dewasa, flushing, eritema & telangiektasis tanpa komedo.", ["status_dermatologis"]),
  ],
  key=["Komedo terbuka/tertutup dengan papul-pustul sedikit di wajah remaja", "Tanpa nodul/kista (ringan)", "Pencetus: hormon, kosmetik, memencet"],
  teach=["Efek terapi akne baru tampak 6–8 minggu; retinoid dapat memerah/mengelupas di awal — oles tipis malam hari.", "Antibiotik topikal selalu dikombinasi benzoil peroksida untuk mencegah resistansi."],
  plan=dict(topics=["onset", "pola", "kebiasaan", "riwayat_penyakit", "keparahan", "keluhan_lain"],
            exams=[("status_dermatologis", "kunci", "Jenis & jumlah lesi (derajat akne), hirsutisme.")]),
  disp=[("rawat_jalan", "Terapi topikal kombinasi 8–12 minggu, edukasi perawatan kulit; kontrol 6–8 minggu.")],
  mg=["Cuci muka 2 × sehari dengan pembersih lembut; kosmetik non-komedogenik; jangan memencet.", "Retinoid topikal (tretinoin 0,025%) malam hari ± benzoil peroksida 2,5–5% pagi.",
      "Papulopustul: tambahkan klindamisin topikal (selalu bersama benzoil peroksida).", "Tabir surya; rujuk bila nodulokistik/berparut."],
  ap=["Tentukan derajat akne (komedonal, papulopustular, nodulokistik).", "Cari pencetus & tanda hiperandrogenisme."],
  refs=REF_KK + ["Kelompok Studi Dermatologi Kosmetik Indonesia. Konsensus Akne (2019)"])

# 8 ---------------------------------------------------------------------------------- hidradenitis supurativa
D(id="hidradenitis_supurativa", name="Hidradenitis supurativa", aka=["Bisul ketiak berulang", "Acne inversa", "Hidradenitis"],
  sys=SYS, prev=0.4,
  summary="Penyakit radang kronik-kambuhan folikel rambut di area lipatan (aksila, inguinal, submamaria, perianal): nodus nyeri dalam yang berulang di tempat sama, menjadi abses, sinus/terowongan berdrainase, dan parut (stadium Hurley I–III). Lebih sering pada perempuan muda, obesitas, perokok. Bukan infeksi primer — antibiotik jangka panjang anti-inflamasi, berhenti merokok, turunkan BB; rujuk untuk tindakan bila berat.",
  day=(30, 365), ages=[(16, 30, 4), (31, 45, 3)], male=0.35,
  traits=[("hurley2", 0.4), ("merokok", 0.35), ("obesitas_menyertai", 0.45)],
  tl={"hurley2": "Hurley II (sinus & parut).", "merokok": "Perokok.", "obesitas_menyertai": "Obesitas."}, tc={"obesitas_menyertai": "obesitas"},
  sym=[("bisul", 1), ("demam", 0.1)],
  cc=["bisul"], mis=["bisul biasa", "kurang bersih", "deodoran"], fears=["infeksi terus", "harus operasi"],
  ana={
      "onset": [("Sudah dua tahun, Dok, bisul di ketiak kambuh terus di tempat yang sama.", "Kronik berulang di lokasi sama")],
      "lokasi": [("Di ketiak kanan-kiri dan lipat paha, Dok.", "Lipatan (aksila & inguinal)")],
      "karakter": [("Sekarang ada lubang-lubang yang terus keluar cairan, kulitnya jadi berparut, Dok.", "Sinus berdrainase & parut (Hurley II)", T("hurley2")),
                   ("Benjolan sakit dalam, kadang pecah lalu sembuh, terus muncul lagi, Dok.", "Nodus/abses berulang tanpa sinus (Hurley I)", NT("hurley2"))],
      "kebiasaan": [("Saya merokok sebungkus sehari, Dok.", "Merokok", T("merokok")), ("Berat badan saya berlebih, Dok.", "Obesitas", T("obesitas_menyertai"))],
      "riwayat_obat": [("Sudah berkali-kali minum antibiotik, Dok, sembuh sebentar lalu kambuh.", "Kambuh setelah antibiotik jangka pendek")],
  },
  f=DS("Aksila kanan & kiri, lipat paha", "Nodus inflamasi nyeri multipel, beberapa abses, sinus berdrainase & parut (Hurley II)", when=T("hurley2"))
    + DS("Aksila kanan & kiri", "Nodus inflamasi nyeri & abses berulang tanpa sinus (Hurley I), parut minimal", when=NT("hurley2"))
    + [F("timbangan", "imt", (28, 34), when=T("obesitas_menyertai"))],
  dd=[
      X("skrofuloderma", "Skrofuloderma: KGB konglomerasi tidak nyeri dengan fistel & ulkus bergaung, gejala TB, Mantoux kuat positif.", ["status_dermatologis", "riwayat_penyakit"], must=True),
      X("furunkel_karbunkel", "Furunkel: nodus folikular akut tunggal, tidak berulang di lipatan yang sama dengan sinus.", ["onset", "status_dermatologis"]),
      X("limfadenitis", "Limfadenitis: KGB aksila nyeri dengan fokus infeksi di lengan, tanpa sinus/parut.", ["status_dermatologis"]),
  ],
  key=["Nodus/abses nyeri berulang di lipatan (aksila, inguinal)", "Sinus berdrainase & parut (Hurley II)", "Obesitas, merokok"],
  plan=dict(topics=["onset", "lokasi", "karakter", "kebiasaan", "riwayat_obat", "keluhan_lain"],
            exams=[("status_dermatologis", "kunci", "Distribusi, sinus, stadium Hurley."), ("timbangan", "pendukung", "Obesitas.")]),
  disp=[("rawat_jalan", "Modifikasi gaya hidup, antiseptik, antibiotik topikal/oral jangka panjang; rujuk bila Hurley II–III berat.", None, ["rujuk_spesialis"])],
  mg=["Berhenti merokok, turunkan BB, pakaian longgar, hindari cukur kasar.", "Antiseptik (klorheksidin) & klindamisin topikal untuk Hurley I.",
      "Doksisiklin/tetrasiklin oral 12 minggu untuk lesi luas/Hurley II; analgesik.", "Insisi drainase abses akut; rujuk untuk deroofing/eksisi atau terapi biologik."],
  ap=["Kenali rekurensi di lipatan & sinus.", "Tentukan stadium Hurley; singkirkan TB kulit."],
  refs=REF_KK)

